    "flyco_api::app::list_sessions": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Response */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description What it is doing, for an [`Active`](SessionState::Active) session.
                         *
                         *     What lets the home list say `Working` and `Needs input` rather than
                         *     reading every running session as `Idle`: the facts behind those two
                         *     live in the relay and in the `approvals` table, and this is the
                         *     control plane's own answer, carried on the row the list is built
                         *     from (docs/ux.md §6).
                         *
                         *     Meaningless for every other state, and the UI ignores it there — a
                         *     session keeps the activity it had when it was paused, interrupted or
                         *     archived rather than being reset to a position it was never in.
                         */
                        activity: components["schemas"]["SessionActivity"];
                        branch?: null | components["schemas"]["BranchName"];
                        /**
                         * Format: int64
                         * @description When it was created, seconds since the Unix epoch.
                         */
                        created_at_unix: number;
                        /** @description Which coding harness drives it. */
                        harness: components["schemas"]["HarnessKind"];
                        /** @description Identifier. */
                        id: components["schemas"]["Uuid"];
                        interrupted_reason?: null | components["schemas"]["InterruptedReason"];
                        /**
                         * Format: int64
                         * @description Last time anything happened on it, seconds since the Unix epoch.
                         */
                        last_active_unix: number;
                        /** @description Whether flyco or the user chose the machine it runs on. */
                        machine_origin: components["schemas"]["MachineOrigin"];
                        /** @description Repository it works in. */
                        repo: components["schemas"]["RepoSlug"];
                        /** @description Where it is in its lifecycle. */
                        state: components["schemas"]["SessionState"];
                        /**
                         * @description What the session is called in a list.
                         *
                         *     Opens as the excerpt of the first prompt and is editable through
                         *     `PATCH /v1/sessions/{id}`. Never empty: a row with no name would
                         *     leave every list entry identified by a UUID.
                         */
                        title: string;
                    }[];
                };
            };
        };
    };
    "flyco_api::app::create_session": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /** @description Extractor arguments */
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * @description Branch to check out. Untyped for the same reason as
                     *     [`repo`](Self::repo): the control plane parses it into a
                     *     [`BranchName`](crate::repo::BranchName) and refuses anything git
                     *     would.
                     *
                     *     Omitted, the control plane asks GitHub for the repository's default
                     *     branch and records *that*, so a session always names the branch it
                     *     works on rather than leaving every later reader to guess.
                     */
                    branch?: string | null;
                    /** @description Spending limit for the whole session. */
                    budget_limit: components["schemas"]["Usd"];
                    /** @description Which coding harness drives the session. */
                    harness: components["schemas"]["HarnessKind"];
                    machine?: null | components["schemas"]["MachineChoice"];
                    /**
                     * @description What the agent should do first.
                     *
                     *     Required, because a session with nothing to do is a machine nobody
                     *     asked for: the prompt is recorded as the session's first user
                     *     message and delivered to the daemon as soon as one connects. Its
                     *     excerpt is also the session's opening [`title`](SessionSummary::title).
                     */
                    prompt: string;
                    /**
                     * @description Repository to work in, `owner/name`. Untyped here because it is
                     *     untrusted input; the control plane parses it into a
                     *     [`RepoSlug`](crate::repo::RepoSlug) and rejects anything else.
                     */
                    repo: string;
                    /**
                     * @description Whether to ask for interruptible spot capacity when flyco picks the
                     *     machine. Ignored when [`Self::machine`] names a type, because that
                     *     choice already carries its own `spot`.
                     */
                    spot?: boolean;
                };
            };
        };
        responses: {
            /** @description The resource that was created. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["SessionSummary"] & {
                        /** @description Budget accounting as of this request. */
                        budget: components["schemas"]["BudgetView"];
                        /**
                         * @description Why the session is [`SessionState::Failed`], in the provider's own
                         *     words where it has any.
                         *
                         *     `None` for every other state. A failed session that could not say
                         *     why would leave the user with a dead session and no idea whether to
                         *     retry it, pick another region, or ask for a quota increase.
                         */
                        failure?: string | null;
                    };
                };
            };
        };
    };
